import { MainWrapper, Headline, Subheadline, ContentWrapper } from "./index.stitches";

function Topper() {
  return (
    <header>
      <MainWrapper>
        <ContentWrapper>
          <div>

          </div>
          <Headline><span>Hi, I’m</span> Agnes!</Headline>
          <Subheadline>
            I am currently a D.C.-based Designer at The Washington Post, where I
            design and develop interactive stories.
          </Subheadline>
        </ContentWrapper>
      </MainWrapper>
    </header>
  );
}

export default Topper;
